  async function write(action,extra,token,expected=model.version){if(saving||!current(token))return null;saving=true;try{const headers={'content-type':'application/json'};if(['create','open','close'].includes(action)&&EDITOR)headers['x-kokkiri-editor']=EDITOR;const response=await api('/api/live-courts',{method:'POST',headers,body:JSON.stringify({version:expected,action,...extra})});if(!current(token))return null;adopt(response?.data||model);render(token);return model;}finally{saving=false;}}
  async function refresh(error,token){message(error.message||'저장하지 못했어요.',true);if(conflict(error)&&current(token))try{await load(token);}catch(reason){message(reason.message||'최신 대진을 불러오지 못했어요.',true);}}
